import (
	"context"
	"fmt"
)

// OrderClient is defined here, at the consumer, sized to what OrderService
// actually calls -- not next to whatever concrete type implements it.
type OrderClient interface {
	Send(ctx context.Context, o Order) error
}

type Service struct {
	client OrderClient
}

func NewService(client OrderClient) *Service {
	return &Service{client: client}
}

func (s *Service) Submit(ctx context.Context, o Order) error {
	// ... validation / mapping on the caller's ctx ...

	if err := s.client.Send(ctx, o); err != nil {
		return fmt.Errorf("submit order %s: %w", o.ID, err)
	}
	return nil
}
```

