func (s *OrderService) PlaceOrder(ctx context.Context, req PlaceOrderRequest) (Order, error) {
    if err := req.Validate(); err != nil {
        return Order{}, fmt.Errorf("validating order request: %w", err)
    }

    ctx, cancel := context.WithTimeout(ctx, s.downstreamTimeout)
    defer cancel()

    resp, err := s.client.Submit(ctx, req)
    if err != nil {
        return Order{}, fmt.Errorf("submitting order %q to client: %w", req.OrderID, err)
    }
    if resp.Status != ClientStatusAccepted {
        return Order{}, fmt.Errorf("order %q rejected by client: %w", req.OrderID, ErrOrderRejected)
    }

    return toOrder(resp), nil
}
```

That gives you: caller's deadline honored, downstream call bounded, both failure paths wrapped with `%w` so a caller can `errors.Is(err, ErrOrderRejected)` and still see the underlying transport error via `errors.As`.

